<?php if (!defined('JOBS_APP')) { http_response_code(403); exit('Acceso denegado'); } ?>
<?php $d=db(); ?><section class="jobs-wrap"><div class="jobs-actions"><h1>Panel administrativo</h1><form method="post" action="/admin/salir"><input type="hidden" name="csrf" value="<?=csrf()?>"><button class="btn">Salir</button></form></div><?php if(!$d)echo '<p class="jobs-msg">Configura DB_HOST, DB_NAME, DB_USER y DB_PASSWORD para guardar cambios.</p>';?><div class="jobs-panel"><h2>Inventario</h2><table class="jobs-table"><tr><th>Producto</th><th>Precio</th><th>Stock</th><th>Editar</th></tr><?php foreach(products(true) as $p){?><tr><td><?=h($p['nombre'])?></td><td><?=money($p['precio'])?></td><td><?=h($p['stock'])?></td><td><a href="/admin?editar=<?=h(rawurlencode($p['id']))?>">Editar</a></td></tr><?php }?></table></div><?php $edit=null;foreach(products(true) as $p)if($p['id']===($_GET['editar']??''))$edit=$p;?><div class="jobs-panel"><h2><?=$edit?'Editar producto':'Nuevo producto'?></h2><form class="jobs-form" action="/admin/producto/guardar" method="post"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=h($edit['id']??'')?>"><label>Nombre<input name="nombre" required value="<?=h($edit['nombre']??'')?>"></label><label>Categoría<select name="categoria"><option value="gorra" <?=($edit['categoria']??'')==='gorra'?'selected':''?>>Gorra</option><option value="reloj" <?=($edit['categoria']??'')==='reloj'?'selected':''?>>Reloj</option></select></label><label>Descripción<textarea name="descripcion"><?=h($edit['descripcion']??'')?></textarea></label><label>Precio COP<input type="number" min="0" name="precio" required value="<?=h($edit['precio']??0)?>"></label><label>Stock<input type="number" min="0" name="stock" required value="<?=h($edit['stock']??0)?>"></label><label>Imagen (ruta dentro de static/img/)<input name="imagen" required value="<?=h($edit['imagen']??'productos/gorra-azul-royal.webp')?>"></label><label><input type="checkbox" name="destacado" <?=!empty($edit['destacado'])?'checked':''?>> Destacado</label><label><input type="checkbox" name="visible" <?=!$edit||!empty($edit['visible'])?'checked':''?>> Visible</label><button class="btn btn-primary">Guardar producto</button></form></div><div class="jobs-panel"><h2>Pedidos recibidos</h2><table class="jobs-table"><tr><th>Referencia</th><th>Cliente</th><th>Total</th><th>Estado</th><th>Actualizar</th></tr><?php if($d){foreach($d->query('SELECT * FROM jobs_pedidos ORDER BY id DESC LIMIT 100') as $r){?><tr><td><?=h($r['referencia'])?></td><td><?=h($r['cliente'])?><br><?=h($r['telefono'])?><br><small><?=h($r['items_json'])?></small></td><td><?=money($r['total'])?></td><td><?=h($r['estado'])?></td><td><form method="post" action="/admin/pedido/estado"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=h($r['id'])?>"><select name="estado"><?php foreach(['Pendiente','Confirmado','Enviado','Entregado','Cancelado'] as $e)echo '<option '.($r['estado']===$e?'selected':'').'>'.h($e).'</option>';?></select><button>Guardar</button></form></td></tr><?php }}?></table></div><div class="jobs-panel"><h2>Reseñas pendientes</h2><?php if($d)foreach($d->query('SELECT * FROM jobs_resenas WHERE aprobada=0 ORDER BY id DESC LIMIT 30') as $r){?><p><?=h($r['cliente'])?> — <?=h($r['comentario'])?></p><form method="post" action="/admin/resena/aprobar"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=h($r['id'])?>"><input type="hidden" name="aprobar" value="1"><button class="btn">Aprobar</button></form><?php }?></div></section>
